def weightedOuterReader (η : ℝ → 𝕜) (hη : StronglyMeasurable η)
    (hb : ∀ x, ‖η x‖ ≤ 1) : Lp E p unitIntervalMeasure →L[𝕜] E :=
  (probabilityLpIntegral (𝕜 := 𝕜)).comp (vectorBoundedMultiply η hη hb)

